CREATE TABLE IF NOT EXISTS purchase_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, initiator VARCHAR(80) NOT NULL, subject VARCHAR(300) NOT NULL, description TEXT NOT NULL, amount NUMERIC(15,2) NOT NULL, due_date DATE NOT NULL, status VARCHAR(40) NOT NULL, comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS procedures (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL UNIQUE REFERENCES purchase_requests(id), title VARCHAR(300) NOT NULL, conditions TEXT NOT NULL, deadline DATE NOT NULL, status VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS offers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, procedure_id BIGINT NOT NULL REFERENCES procedures(id), supplier VARCHAR(80) NOT NULL, price NUMERIC(15,2) NOT NULL, terms TEXT NOT NULL, status VARCHAR(40) NOT NULL, review_state VARCHAR(40), comment TEXT, clarification_deadline TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(procedure_id,supplier));
CREATE TABLE IF NOT EXISTS results (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, procedure_id BIGINT NOT NULL UNIQUE REFERENCES procedures(id), offer_id BIGINT REFERENCES offers(id), outcome VARCHAR(40) NOT NULL, comment TEXT);
CREATE TABLE IF NOT EXISTS contracts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, result_id BIGINT NOT NULL UNIQUE REFERENCES results(id), number VARCHAR(100) NOT NULL UNIQUE, subject VARCHAR(300) NOT NULL, amount NUMERIC(15,2) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(40) NOT NULL, execution_notes TEXT, comment TEXT, edo_status VARCHAR(40), edo_reference VARCHAR(100), edo_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS contract_documents (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_id BIGINT NOT NULL REFERENCES contracts(id), version INT NOT NULL, filename VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, content BYTEA NOT NULL, UNIQUE(contract_id,version));
CREATE TABLE IF NOT EXISTS approvals (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, contract_id BIGINT NOT NULL REFERENCES contracts(id), document_id BIGINT NOT NULL REFERENCES contract_documents(id), actor VARCHAR(80) NOT NULL, decision VARCHAR(40) NOT NULL, comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient VARCHAR(80) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
